import {
  forwardRef,
  useId,
  type InputHTMLAttributes,
  type ReactNode,
} from "react";
import "./LayeredInput.css";

export type LayeredInputTone =
  | "neutral"
  | "copper"
  | "green"
  | "gold";

export type LayeredInputSize =
  | "small"
  | "medium"
  | "large";

export interface LayeredInputProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, "size"> {
  label: ReactNode;
  description?: ReactNode;
  error?: ReactNode;
  tone?: LayeredInputTone;
  inputSize?: LayeredInputSize;
  fullWidth?: boolean;
  leadingContent?: ReactNode;
  trailingContent?: ReactNode;
}

export const LayeredInput = forwardRef<HTMLInputElement, LayeredInputProps>(
  function LayeredInput(
    {
      label,
      description,
      error,
      tone = "neutral",
      inputSize = "medium",
      fullWidth = false,
      leadingContent,
      trailingContent,
      className = "",
      id,
      disabled,
      readOnly,
      required,
      ...props
    },
    ref
  ) {
    const generatedId = useId();
    const inputId = id || `layered-input-${generatedId}`;
    const descriptionId = description ? `${inputId}-description` : undefined;
    const errorId = error ? `${inputId}-error` : undefined;

    const describedBy =
      [props["aria-describedby"], descriptionId, errorId]
        .filter(Boolean)
        .join(" ") || undefined;

    const isInvalid =
      Boolean(error) ||
      props["aria-invalid"] === true ||
      props["aria-invalid"] === "true";

    const wrapperClasses = [
      "layered-input-wrapper",
      fullWidth ? "layered-input-wrapper--full-width" : "",
      className,
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <div
        className={wrapperClasses}
        data-tone={tone}
        data-size={inputSize}
        data-disabled={disabled ? "true" : undefined}
        data-readonly={readOnly ? "true" : undefined}
        data-invalid={isInvalid ? "true" : undefined}
      >
        <div className="layered-input__label-row">
          <label htmlFor={inputId} className="layered-input__label">
            {label}
            {required && (
              <span className="layered-input__required" aria-hidden="true">
                {" *"}
              </span>
            )}
          </label>
        </div>

        <div className="layered-input__casing">
          <div className="layered-input__surface">
            {leadingContent && (
              <span
                className="layered-input__leading"
                aria-hidden={
                  typeof leadingContent === "string" ||
                  typeof leadingContent === "number"
                    ? true
                    : undefined
                }
              >
                {leadingContent}
              </span>
            )}
            <input
              ref={ref}
              id={inputId}
              disabled={disabled}
              readOnly={readOnly}
              required={required}
              aria-describedby={describedBy}
              aria-invalid={isInvalid ? true : undefined}
              className="layered-input__control"
              {...props}
            />
            {trailingContent && (
              <span
                className="layered-input__trailing"
                aria-hidden={
                  typeof trailingContent === "string" ||
                  typeof trailingContent === "number"
                    ? true
                    : undefined
                }
              >
                {trailingContent}
              </span>
            )}
          </div>
        </div>

        {description && (
          <div id={descriptionId} className="layered-input__description">
            {description}
          </div>
        )}

        {error && (
          <div id={errorId} className="layered-input__error" role="alert">
            {error}
          </div>
        )}
      </div>
    );
  }
);

.layered-input-wrapper {
    /* Default neutral tone */
    --input-tone-accent: #8c8f94;
    --input-tone-focus: var(--control-focus);

    /* Default medium size */
    --input-font-size: 0.95rem;
    --input-label-font-size: 0.875rem;
    --input-padding-y: 9px;
    --input-padding-x: 14px;
    --input-surface-height: 44px;

    display: inline-flex;
    flex-direction: column;
    gap: 6px;
    box-sizing: border-box;

    width: 100%;
    max-width: 420px;

    color: var(--color-text);
}

.layered-input-wrapper--full-width {
    max-width: none;
}

/* Label Row & Label */

.layered-input__label-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.layered-input__label {
    color: var(--color-text);

    font-size: var(--input-label-font-size);
    font-weight: 600;
    line-height: 1.3;
    letter-spacing: 0.015em;

    transition: color var(--duration-fast) var(--ease-control);
}

.layered-input__required {
    color: var(--input-tone-accent);
}

/* Outer Structural Casing */

.layered-input__casing {
    box-sizing: border-box;

    padding: 3px;
    border: 2px solid var(--control-shell-border);
    border-radius: var(--control-radius-outer);

    background:
        linear-gradient(180deg,
            var(--input-casing-top) 0%,
            var(--input-casing-bottom) 100%);

    box-shadow:
        0 2px 5px rgb(0 0 0 / 30%),
        inset 0 1px rgb(255 255 255 / 6%);

    transition:
        box-shadow var(--duration-fast) var(--ease-control),
        border-color var(--duration-fast) var(--ease-control),
        outline var(--duration-fast) var(--ease-control);
}

/* Inner Recessed Surface */

.layered-input__surface {
    position: relative;
    display: flex;
    align-items: center;
    box-sizing: border-box;

    min-height: var(--input-surface-height);

    border: 2px solid var(--control-trench);
    border-radius: var(--control-radius-inner);

    background:
        linear-gradient(180deg,
            var(--input-surface-bg-top) 0%,
            var(--input-surface-bg-bottom) 100%);

    color: var(--color-text);

    box-shadow:
        inset 0 2px 4px rgb(0 0 0 / 50%),
        inset 0 -1px 1px rgb(255 255 255 / 3%);

    transition:
        border-color var(--duration-fast) var(--ease-control),
        box-shadow var(--duration-fast) var(--ease-control),
        background var(--duration-fast) var(--ease-control);

    overflow: hidden;
}

/* Native Input Control */

.layered-input__control {
    flex: 1 1 auto;
    min-width: 0;

    padding: var(--input-padding-y) var(--input-padding-x);
    border: none;
    outline: none;

    background: transparent;
    color: var(--color-text);

    font-family: inherit;
    font-size: var(--input-font-size);
    line-height: 1.4;

    box-sizing: border-box;
}

.layered-input__control::placeholder {
    color: var(--color-text-muted);
    opacity: 0.65;
}

/* Leading & Trailing Content */

.layered-input__leading,
.layered-input__trailing {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;

    color: var(--color-text-muted);
    font-size: 0.9em;

    padding-inline: 10px;
    user-select: none;
}

.layered-input__leading {
    padding-right: 0;
}

.layered-input__trailing {
    padding-left: 0;
}

/* Supporting Text & Error Text */

.layered-input__description {
    margin-top: 2px;
    color: var(--color-text-muted);

    font-size: 0.8rem;
    line-height: 1.4;
}

.layered-input__error {
    margin-top: 2px;
    color: var(--control-error-text, var(--control-error));

    font-size: 0.8rem;
    font-weight: 500;
    line-height: 1.4;
}

/* Tone Variants */

.layered-input-wrapper[data-tone="copper"] {
    --input-tone-accent: var(--tone-copper-light);
    --input-tone-focus: var(--tone-copper-light);
}

.layered-input-wrapper[data-tone="green"] {
    --input-tone-accent: var(--tone-green-light);
    --input-tone-focus: var(--tone-green-light);
}

.layered-input-wrapper[data-tone="gold"] {
    --input-tone-accent: var(--tone-gold-light);
    --input-tone-focus: var(--tone-gold-light);
}

.layered-input-wrapper[data-tone="neutral"] {
    --input-tone-accent: var(--tone-neutral-light);
    --input-tone-focus: var(--control-focus);
}

/* Size Variants */

.layered-input-wrapper[data-size="small"] {
    --input-font-size: 0.85rem;
    --input-label-font-size: 0.8rem;
    --input-padding-y: 6px;
    --input-padding-x: 10px;
    --input-surface-height: 36px;
}

.layered-input-wrapper[data-size="medium"] {
    --input-font-size: 0.95rem;
    --input-label-font-size: 0.875rem;
    --input-padding-y: 9px;
    --input-padding-x: 14px;
    --input-surface-height: 44px;
}

.layered-input-wrapper[data-size="large"] {
    --input-font-size: 1.05rem;
    --input-label-font-size: 0.95rem;
    --input-padding-y: 12px;
    --input-padding-x: 18px;
    --input-surface-height: 52px;
}

/* Interaction & States */

/* Hover */
.layered-input-wrapper:not([data-disabled="true"]):not([data-readonly="true"]):hover .layered-input__casing {
    box-shadow:
        0 3px 8px rgb(0 0 0 / 40%),
        inset 0 1px rgb(255 255 255 / 9%);
}

.layered-input-wrapper:not([data-disabled="true"]):not([data-readonly="true"]):hover .layered-input__surface {
    border-color: #2a221c;
}

/* Focus */
.layered-input-wrapper:not([data-disabled="true"]):focus-within .layered-input__casing {
    outline: 3px solid var(--input-tone-focus);
    outline-offset: 2px;
}

.layered-input-wrapper:not([data-disabled="true"]):focus-within .layered-input__surface {
    border-color: var(--input-tone-focus);
    box-shadow:
        0 0 0 1px var(--input-tone-focus),
        inset 0 2px 4px rgb(0 0 0 / 60%);
}

/* Disabled State */
.layered-input-wrapper[data-disabled="true"] {
    opacity: 0.5;
    filter: grayscale(0.45);
    cursor: not-allowed;
}

.layered-input-wrapper[data-disabled="true"] .layered-input__control,
.layered-input-wrapper[data-disabled="true"] .layered-input__label {
    cursor: not-allowed;
}

.layered-input-wrapper[data-disabled="true"] .layered-input__surface {
    background: #141516;
}

/* Read-Only State */
.layered-input-wrapper[data-readonly="true"] {
    cursor: default;
}

.layered-input-wrapper[data-readonly="true"] .layered-input__control {
    cursor: default;
}

.layered-input-wrapper[data-readonly="true"] .layered-input__surface {
    background: #232426;
    border-color: #151617;
    box-shadow: inset 0 1px 2px rgb(0 0 0 / 30%);
}

.layered-input-wrapper[data-readonly="true"] .layered-input__casing {
    background: linear-gradient(180deg, #3d3733, #2d2724);
    box-shadow: none;
}

/* Error State (takes priority over selected tone) */
.layered-input-wrapper[data-invalid="true"] .layered-input__label {
    color: var(--control-error);
}

.layered-input-wrapper[data-invalid="true"] .layered-input__surface {
    border-color: var(--control-error);
}

.layered-input-wrapper[data-invalid="true"]:focus-within .layered-input__casing {
    outline-color: var(--control-error);
}

.layered-input-wrapper[data-invalid="true"]:focus-within .layered-input__surface {
    border-color: var(--control-error);
    box-shadow:
        0 0 0 1px var(--control-error),
        inset 0 2px 4px rgb(0 0 0 / 60%);
}

/* Responsive Narrow Screen Support */

@media (max-width: 640px) {
    .layered-input-wrapper {
        max-width: 100%;
    }
}

/* Reduced Motion */

@media (prefers-reduced-motion: reduce) {
    .layered-input-wrapper,
    .layered-input__casing,
    .layered-input__surface,
    .layered-input__label {
        transition: none;
    }
}
